def possible_change(coins, total):
    if total == 0:
        return 1
    if total < 0:
        return 0
    if not coins:
        return 0

    first, *rest = coins
    return possible_change(coins, total - first) + possible_change(rest, total)

# Python 3
def possible_change(coins, total):
    if total < 0:
        return 0
    ways = [0] * (total + 1)
    ways[0] = 1
    for coin in coins:
        for amount in range(coin, total + 1):
            ways[amount] += ways[amount - coin]
    return ways[total]

