import io
import sys
from contextlib import redirect_stdout

def solve(text):
    def program():
        n, m = map(int, input().split())
        p = []
        c = []
        f = []
        for i in range(n):
            l = list(map(int, input().split()))
            p.append(l[0])
            c.append(l[1])
            f.append(set(l[2:]))
        for i in range(n):
            for j in range(n):
                if p[i] >= p[j]:
                    if f[j].issuperset(f[i]):
                        if p[i] > p[j] or f[j] != f[i]:
                            print('Yes')
                            exit(0)
        print('No')
    previous = sys.stdin
    output = io.StringIO()
    try:
        sys.stdin = io.StringIO(text)
        with redirect_stdout(output):
            program()
    except SystemExit as status:
        if status.code not in (None, 0):
            raise
    finally:
        sys.stdin = previous
    return output.getvalue().strip()

